/**
 * Next per-project issue number. Archived rows and the persistent high-water
 * mark both count, so a number remains retired after an issue moves away.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const counter = db
    .select({ value: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(
      and(
        eq(issueNumberCounters.orgId, orgId),
        eq(issueNumberCounters.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, counter?.value ?? 0) + 1;
}

/** Retains an issued number after its row leaves the project. */
function rememberIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): void {
  const db = getDb();
  const current = db
    .select({ lastNumber: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(
      and(
        eq(issueNumberCounters.orgId, orgId),
        eq(issueNumberCounters.projectId, projectId),
      ),
    )
    .get();

  if (current === undefined) {
    db.insert(issueNumberCounters)
      .values({ orgId, projectId, lastNumber: number })
      .run();
  } else if (number > current.lastNumber) {
    db.update(issueNumberCounters)
      .set({ lastNumber: number })
      .where(
        and(
