/** Retains an issued number after its row leaves the project. */
function rememberIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): void {
  const db = getDb();
  const current = db
    .select({ lastNumber: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(
      and(
        eq(issueNumberCounters.orgId, orgId),
        eq(issueNumberCounters.projectId, projectId),
      ),
    )
    .get();

  if (current === undefined) {
    db.insert(issueNumberCounters)
      .values({ orgId, projectId, lastNumber: number })
      .run();
  } else if (number > current.lastNumber) {
    db.update(issueNumberCounters)
      .set({ lastNumber: number })
      .where(
        and(
          eq(issueNumberCounters.orgId, orgId),
          eq(issueNumberCounters.projectId, projectId),
        ),
      )
      .run();
  }
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  rememberIssueNumber(input.orgId, input.projectId, issueNumber);

  if (input.labelIds.length > 0) {
    db.insert(issueLabels)
      .values(
        input.labelIds.map((labelId) => ({
          orgId: input.orgId,
          issueId: row.id,
          labelId,
        })),
      )
      .run();
  }

  return toIssue(row, input.labelIds);
  return toIssue(row);
}

/**
 * Re-points an issue at another project. The optional number supports the
 * import tool's second-pass renumbering; normal issue moves supply the
 * destination project's allocated number.
 */
export async function relocateIssue(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  number?: number,
): Promise<Issue> {
  const db = getDb();
  const current = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const row = db
    .update(issues)
    .set({
      projectId,
      ...(number === undefined ? {} : { number }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  rememberIssueNumber(
    orgId,
    current.projectId as ProjectId,
    current.number,
  );
  rememberIssueNumber(orgId, projectId, row.number);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

